        #include "network_config_parser.h"

/**
 * 解析网络配置参数
 * @param buffer 输入的网络数据包缓冲区
 * @param buffer_size 缓冲区大小
 * @param params 用于存储解析出的参数的指针数组
 * @param param_count 要解析的参数数量
 * @return 成功解析的参数数量
 */
int parse_network_config_params(char* buffer, int buffer_size, char** params, int param_count) {
    if (buffer == NULL || params == NULL || param_count <= 0 || buffer_size <= 0) {
        return 0;
    }

    int parsed_count = 0;
    int current_pos = 0;

    // 循环处理每个参数
    for (int i = 0; i < param_count && current_pos < buffer_size; i++) {
        // 检查是否还有足够的空间来存储参数
        if (current_pos >= buffer_size) {
            break;
        }

        // 查找参数长度（假设参数格式为：[长度字节][参数值]）
        if (current_pos + 1 > buffer_size) {
            break;
        }

        unsigned char param_len = (unsigned char)buffer[current_pos];
        current_pos++;

        // 检查参数长度是否有效
        if (param_len == 0 || current_pos + param_len > buffer_size) {
            continue; // 跳过无效参数，继续处理下一个
        }

        // 为参数分配内存并复制参数值
        params[i] = (char*)malloc(param_len + 1); // +1 for null terminator
        if (params[i] == NULL) {
            // 内存分配失败，回退已分配的内存
            for (int j = 0; j < i; j++) {
                free(params[j]);
                params[j] = NULL;
            }
            return 0;
        }

        // 复制参数值
        memcpy(params[i], buffer + current_pos, param_len);
        params[i][param_len] = '\0'; // 添加字符串结束符

        // 更新位置
        current_pos += param_len;
        parsed_count++;
    }

    return parsed_count;
}
