int main() {
    printf("Security Test: Buffer Overflow Detection\n");

    // Test 1: Attempt to trigger buffer overflow with large buffer_size
    printf("Test 1: Large buffer_size parameter\n");
    char* large_buffer = malloc(1000000);  // Allocate large buffer
    if (large_buffer) {
        memset(large_buffer, 'A', 999999);  // Fill with 'A's
        large_buffer[999999] = '\0';        // Null terminate

        char* params[1];
        int result = parse_network_config_params(large_buffer, 1000000, params, 1);
        printf("Result: %d\n", result);

        free(large_buffer);
    }

    // Test 2: Buffer with crafted content to potentially cause overflow
    printf("\nTest 2: Crafted buffer content\n");
    char crafted_buffer[1000];
    memset(crafted_buffer, 'B', sizeof(crafted_buffer));
    crafted_buffer[sizeof(crafted_buffer)-1] = '\0';  // Properly null terminate

    char* params2[2];
    int result2 = parse_network_config_params(crafted_buffer, sizeof(crafted_buffer), params2, 2);
    printf("Result: %d\n", result2);

    // Clean up any allocated memory from the function
    for (int i = 0; i < result2 && i < 2; i++) {
        if (params2[i]) {
            free(params2[i]);
        }
    }

    // Test 3: Buffer with many parameters to potentially cause stack overflow
    printf("\nTest 3: Buffer with many parameters\n");
    char many_params_buffer[2000];
    int offset = 0;
    for (int i = 0; i < 50; i++) {
        int written = snprintf(&many_params_buffer[offset], 
                              sizeof(many_params_buffer) - offset, 
                              "param%d=%d", i, i);
        if (written < 0 || written >= sizeof(many_params_buffer) - offset) {
            break;
        }
        offset += written;
        if (offset < sizeof(many_params_buffer) - 1) {
            many_params_buffer[offset] = '\0';
            offset++;
        }
    }

    char* params3[50];
    int result3 = parse_network_config_params(many_params_buffer, sizeof(many_params_buffer), params3, 50);
    printf("Result: %d\n", result3);

    // Clean up any allocated memory from the function
    for (int i = 0; i < result3 && i < 50; i++) {
        if (params3[i]) {
            free(params3[i]);
        }
    }

    // Test 4: Edge case with buffer_size larger than actual buffer
    printf("\nTest 4: Buffer_size larger than actual buffer\n");
    char small_buffer[10] = "test\0";
    char* params4[1];
    int result4 = parse_network_config_params(small_buffer, 1000, params4, 1);  // buffer_size > actual buffer size
    printf("Result: %d\n", result4);

    // Clean up any allocated memory from the function
    for (int i = 0; i < result4 && i < 1; i++) {
        if (params4[i]) {
            free(params4[i]);
        }
    }

    printf("\nSecurity tests completed. Check for sanitizer reports.\n");
    return 0;
}

